```python
import random

import pygame

WIDTH, HEIGHT = 800, 600
FPS = 60
PADDLE_W, PADDLE_H = 12, 90
PADDLE_SPEED = 7
BALL_SIZE = 14
BALL_SPEED = 6
MAX_BALL_SPEED = 14
SPEEDUP = 1.05
WIN_SCORE = 5
SERVE_FRAMES = 60
WHITE = (255, 255, 255)
BLACK = (20, 20, 20)


class Paddle:
    def __init__(self, x):
        self.rect = pygame.Rect(x, (HEIGHT - PADDLE_H) // 2, PADDLE_W, PADDLE_H)

    def move(self, direction):
        self.rect.y = max(0, min(HEIGHT - PADDLE_H, self.rect.y + direction * PADDLE_SPEED))

    def draw(self, screen):
        pygame.draw.rect(screen, WHITE, self.rect)


class Ball:
    def __init__(self):
        self.reset()

    def reset(self):
        self.rect = pygame.Rect(0, 0, BALL_SIZE, BALL_SIZE)
        self.rect.center = (WIDTH // 2, HEIGHT // 2)
        self.vx = BALL_SPEED * random.choice((-1, 1))
        self.vy = random.uniform(-BALL_SPEED, BALL_SPEED)

    def draw(self, screen):
        pygame.draw.rect(screen, WHITE, self.rect)


class Game:
    def __init__(self):
        pygame.init()
        self.screen = pygame.display.set_mode((WIDTH, HEIGHT))
        pygame.display.set_caption("Pong - First to %d" % WIN_SCORE)
        self.clock = pygame.time.Clock()
        self.big_font = pygame.font.SysFont(None, 56)
        self.font = pygame.font.SysFont(None, 32)
        self.reset_match()

    def reset_match(self):
        self.paddles = [Paddle(30), Paddle(WIDTH - 30 - PADDLE_W)]
        self.ball = Ball()
        self.scores = [0, 0]
        self.serve_delay = SERVE_FRAMES
        self.winner = None
        self.running = True

    def run(self):
        while self.running:
            self.clock.tick(FPS)
            self.handle_events()
            self.update()
            self.draw()
        pygame.quit()

    def handle_events(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                self.running = False
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    self.running = False
                elif event.key == pygame.K_SPACE:
                    if self.winner is not None:
                        self.reset_match()
                    elif self.serve_delay > 0:
                        self.serve_delay = 0

    def update(self):
        keys = pygame.key.get_pressed()
        if keys[pygame.K_w]:
            self.paddles[0].move(-1)
        if keys[pygame.K_s]:
            self.paddles[0].move(1)
        if keys[pygame.K_UP]:
            self.paddles[1].move(-1)
        if keys[pygame.K_DOWN]:
            self.paddles[1].move(1)

        if self.winner is not None:
            return
        if self.serve_delay > 0:
            self.serve_delay -= 1
            return

        ball = self.ball
        ball.rect.x += int(ball.vx)
        ball.rect.y += int(ball.vy)

        if ball.rect.top <= 0:
            ball.rect.top = 0
            ball.vy = abs(ball.vy)
        elif ball.rect.bottom >= HEIGHT:
            ball.rect.bottom = HEIGHT
            ball.vy = -abs(ball.vy)

        for i, paddle in enumerate(self.paddles):
            moving_left = ball.vx < 0
            if ball.rect.colliderect(paddle.rect) and (
                (i == 0 and moving_left) or (i == 1 and not moving_left)
            ):
                offset = (ball.rect.centery - paddle.rect.centery) / (PADDLE_H / 2)
                offset = max(-1.0, min(1.0, offset))
                speed = min(abs(ball.vx) * SPEEDUP, MAX_BALL_SPEED)
                ball.vx = speed if i == 0 else -speed
                ball.vy = offset * speed * 0.9
                if i == 0:
                    ball.rect.left = paddle.rect.right
                else:
                    ball.rect.right = paddle.rect.left

        if ball.rect.right < 0:
            self.award_point(1)
        elif ball.rect.left > WIDTH:
            self.award_point(0)

    def award_point(self, player):
        self.scores[player] += 1
        if self.scores[player] >= WIN_SCORE:
            self.winner = player
        else:
            self.ball.reset()
            self.serve_delay = SERVE_FRAMES

    def draw(self):
        self.screen.fill(BLACK)
        for y in range(10, HEIGHT, 40):
            pygame.draw.rect(self.screen, WHITE, (WIDTH // 2 - 2, y, 4, 20))
        for paddle in self.paddles:
            paddle.draw(self.screen)
        self.ball.draw(self.screen)

        for i, x in ((0, WIDTH // 4), (1, WIDTH * 3 // 4)):
            text = self.big_font.render(str(self.scores[i]), True, WHITE)
            self.screen.blit(text, (x - text.get_width() // 2, 20))

        if self.winner is not None:
            msg = self.font.render(
                "Player %d wins! Press SPACE for a new match" % (self.winner + 1),
                True,
                WHITE,
            )
            self.screen.blit(
                msg, (WIDTH // 2 - msg.get_width() // 2, HEIGHT // 2 - msg.get_height() // 2)
            )
        elif self.serve_delay > 0:
            msg = self.font.render("Press SPACE to serve", True, WHITE)
            self.screen.blit(msg, (WIDTH // 2 - msg.get_width() // 2, HEIGHT - 50))

        pygame.display.flip()
